const existingLeads = $('Fetch Existing CRM Leads').first().json.leads || [];
const existingPhones = new Set();
const existingNames = new Set();

for (const l of existingLeads) {
  if (l.phone) {
    let clean = l.phone.replace(/[^0-9+]/g, '');
    if (clean) existingPhones.add(clean);
  }
  if (l.property_name) {
    existingNames.add(l.property_name.trim().toLowerCase());
  }
}

const seenInBatch = new Set();
const output = [];

for (const item of $input.all()) {
  const places = item.json.places || [];

  for (const p of places) {
    let rawPhone = p.phoneNumber || '';
    let cleanPhone = rawPhone.replace(/[^0-9+]/g, '');
    if (cleanPhone.startsWith('69') && cleanPhone.length === 10) cleanPhone = '+30' + cleanPhone;
    else if (cleanPhone.startsWith('30') && !cleanPhone.startsWith('+')) cleanPhone = '+' + cleanPhone;

    let title = (p.title || '').trim();
    let dedupeKey = cleanPhone || title.toLowerCase();

    // 1. Skip if already processed in current batch
    if (!dedupeKey || seenInBatch.has(dedupeKey)) continue;
    seenInBatch.add(dedupeKey);

    // 2. CRITICAL FILTER: Skip if ALREADY in CRM! (Zero AI tokens spent on duplicates)
    if (existingPhones.has(cleanPhone) || existingNames.has(title.toLowerCase())) {
      continue;
    }

    let website = p.website || '';
    if (website.includes('booking.com') || website.includes('airbnb.') || website.includes('tripadvisor.')) {
      website = '';
    }

    // Only take items with valid phone number
    if (cleanPhone.length >= 8) {
      output.push({
        json: {
          property_name: title || 'Greek Vacation Rental',
          phone: cleanPhone,
          website: website,
          address: p.address || 'Nea Kallikrateia, Halkidiki',
          rating: p.rating || 4.8,
          reviews_count: p.ratingCount || 10,
          region: 'Nea Kallikrateia'
        }
      });
    }
  }
}

return output;

