text = text.replace(/```json/gi, '').replace(/```/g, '').trim();
let parsed = {};
try {
  parsed = JSON.parse(text);
} catch(e) {
  parsed = { property_name: 'Greek Rental', notes: text, status: 'ai_audited' };
}

return { json: parsed };
